export function feelers(A, { col = 0x7af27a, h = 1.15 } = {}) { const g = new THREE.Group(); g.position.set(0, 0.5, 0); A.headMesh.add(g); const st = [];
  for (const s of [-1, 1]) { const p = new THREE.Group(); p.position.set(s * 0.24, 0, 0); p.rotation.z = -s * 0.28; g.add(p); put(p, mesh(new THREE.CylinderGeometry(0.035, 0.045, h, 6), M(0x2c2c30)), [0, h / 2, 0]); put(p, new THREE.Mesh(new THREE.SphereGeometry(0.13, 12, 10), basic(col)), [0, h + 0.08, 0]); st.push([p, s]); }
  g.scale.set(1, 0.001, 1); g.visible = false; return { g, set: (k, t = 0) => { g.visible = k > 0.01; g.scale.set(1, Math.max(0.001, k), 1); st.forEach(([p, s]) => { p.rotation.z = -s * 0.28 + Math.sin(t * 9 + s) * 0.12 * Math.min(1, k); p.rotation.x = Math.sin(t * 7 + s * 2) * 0.1; }); } }; }

