  for (const rz of [0.6, -0.6]) put(g, new THREE.Mesh(new THREE.PlaneGeometry(1.3, 0.24), M(0xa8acb4, { roughness: 0.4, metalness: 0.5 })), [Math.sin(0.9) * 2.9, 4.6, Math.cos(0.9) * 2.9], [0, 0.9, rz]);
  // hatch (facing +z, slightly right) + ladder + porthole
  const hatch = put(g, new THREE.Mesh(new THREE.CircleGeometry(1.05, 20), basic(0xffe2a8)), [0.95, 4.0, 2.66], [0, 0.35, 0]); put(g, mesh(new THREE.TorusGeometry(1.08, 0.12, 8, 22), gold), [0.95, 4.0, 2.68], [0, 0.35, 0]);
  const door = put(g, mesh(new THREE.CylinderGeometry(1.05, 1.05, 0.14, 20), hull), [2.3, 4.0, 2.75], [Math.PI / 2, 0, 0.9]);
  for (const sx of [-0.45, 0.45]) put(g, mesh(new THREE.CylinderGeometry(0.05, 0.05, 3.3, 6), steel()), [0.95 + sx, 1.6, 3.2], [0.18, 0, 0]); for (let i = 0; i < 5; i++) put(g, mesh(new THREE.CylinderGeometry(0.04, 0.04, 0.9, 6), steel()), [0.95, 0.4 + i * 0.6, 3.46 - i * 0.11], [0, 0, Math.PI / 2]);
  // legs
  const feet = []; for (const a of [0.78, 2.36, 3.93, 5.5]) { const dx = Math.sin(a), dz = Math.cos(a); const leg = mesh(new THREE.CylinderGeometry(0.11, 0.11, 4.2, 8), steel()); leg.position.set(dx * 3.5, 1.55, dz * 3.5); leg.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), new THREE.Vector3(dx * 0.62, -0.78, dz * 0.62).normalize()); g.add(leg);
    put(g, mesh(new THREE.CylinderGeometry(0.6, 0.7, 0.2, 14), gold), [dx * 4.8, 0.1, dz * 4.8]); feet.push([dx * 4.8, 0.3, dz * 4.8]); }
  // engine bell
  const bell = put(g, mesh(new THREE.CylinderGeometry(0.6, 1.3, 1.5, 18, 1, true), M(0x4a4c54, { metalness: 0.7, roughness: 0.4, side: THREE.DoubleSide })), [0, 1.4, 0]); const glow = put(g, new THREE.Mesh(new THREE.CircleGeometry(1.2, 18), basic(0x8ad8ff, { transparent: true, opacity: 0 })), [0, 0.7, 0], [Math.PI / 2, 0, 0]);
  const under = new THREE.PointLight(0x8ad0ff, 0, 30, 1.5); under.position.set(0, 0.9, 1.5); g.add(under);
  // dish + antenna + lights
  const dish = new THREE.Group(); dish.position.set(-0.9, 8.1, 0); g.add(dish); put(dish, mesh(new THREE.SphereGeometry(0.9, 16, 8, 0, 7, 0, 1.1), M(0xe8eaee, { side: THREE.DoubleSide, roughness: 0.4 })), [0, 0.5, 0], [Math.PI, 0, 0]); put(dish, mesh(new THREE.CylinderGeometry(0.04, 0.04, 0.9, 6), steel()), [0, 0, 0]);
  put(g, mesh(new THREE.CylinderGeometry(0.03, 0.03, 2.0, 6), steel()), [0.8, 8.6, 0]); const beacon = put(g, new THREE.Mesh(new THREE.SphereGeometry(0.12, 10, 8), basic(0xff3a2a)), [0.8, 9.65, 0]);
  const bulbs = []; for (let i = 0; i < 10; i++) { const a = i / 10 * 6.283; bulbs.push(put(g, new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 6), basic(0x30343c)), [Math.sin(a) * 2.78, 5.85, Math.cos(a) * 2.78])); }
  const port = put(g, new THREE.Mesh(new THREE.CircleGeometry(0.5, 16), basic(0xffd890)), [-1.9, 4.5, 2.05], [0, -0.75, 0]); put(g, mesh(new THREE.TorusGeometry(0.52, 0.08, 6, 18), gold), [-1.9, 4.5, 2.06], [0, -0.75, 0]);
